using System.Collections.Generic;public class Solution{List<string>o=new();(char,char)[]p={('0','0'),('1','1'),('6','9'),('8','8'),('9','6')};void F(char[]s,int l,int r){if(l>r){o.Add(new string(s));return;}foreach(var x in p){if(l==0&&r>0&&x.Item1=='0')continue;if(l==r&&x.Item1!=x.Item2)continue;s[l]=x.Item1;s[r]=x.Item2;F(s,l+1,r-1);}}public IList<string> FindStrobogrammatic(int n){F(new char[n],0,n-1);return o;}}
